import bioblend.galaxy
import time

api_key = "[REDACTED_GALAXY_API_KEY]"
gi = bioblend.galaxy.GalaxyInstance(url='https://usegalaxy.org', key=api_key)

history_id = "bbd44e69cb8906b59a0d065f2ef4400c"

# Wait for uploads
for attempt in range(20):
    all_ok = True
    contents = gi.histories.show_history(history_id, contents=True)
    for item in contents:
        if 'regulated' in item['name'] or 'background' in item['name']:
            if item['state'] not in ('ok',):
                all_ok = False
    if all_ok:
        print("All uploads complete!")
        break
    time.sleep(3)

# Find the IDs
up_id = down_id = bg_id = None
for item in contents:
    if item['name'] == 'upregulated_genes.txt':
        up_id = item['id']
    elif item['name'] == 'downregulated_genes.txt':
        down_id = item['id']
    elif item['name'] == 'background_genes.txt':
        bg_id = item['id']

print(f"Up genes: {up_id}")
print(f"Down genes: {down_id}")
print(f"Background: {bg_id}")

# Run gProfiler GOSt for upregulated genes (GO:BP)
tool_id = "toolshed.g2.bx.psu.edu/repos/iuc/gprofiler_gost/gprofiler_gost/0.1.7+galaxy11"

# Upregulated
inputs_up = {
    "input": {"src": "hda", "id": up_id},
    "organism": {
        "select_input_type": "select",
        "organism": "hsapiens"
    },
    "ordered_query": False,
    "advanced_options": {
        "significant": True,
        "measure_underrepresentation": False,
        "evcodes": False,
        "user_threshold": 0.05,
        "correction_method": "gSCS",
        "domain_scope": "annotated"
    },
    "data_sources": {
        "go_sources": "GO:BP",
        "exclude_iea": False
    },
    "tool_settings": {
        "export_plot": False
    }
}

print("\nSubmitting gProfiler for UPREGULATED genes...")
result_up = gi.tools.run_tool(history_id, tool_id, inputs_up)
for job in result_up.get('jobs', []):
    print(f"  Job ID: {job['id']}")
    up_job_id = job['id']
for out in result_up.get('outputs', []):
    print(f"  Output: {out.get('name')} (HID={out.get('hid')})")

# Downregulated
inputs_down = {
    "input": {"src": "hda", "id": down_id},
    "organism": {
        "select_input_type": "select",
        "organism": "hsapiens"
    },
    "ordered_query": False,
    "advanced_options": {
        "significant": True,
        "measure_underrepresentation": False,
        "evcodes": False,
        "user_threshold": 0.05,
        "correction_method": "gSCS",
        "domain_scope": "annotated"
    },
    "data_sources": {
        "go_sources": "GO:BP",
        "exclude_iea": False
    },
    "tool_settings": {
        "export_plot": False
    }
}

print("\nSubmitting gProfiler for DOWNREGULATED genes...")
result_down = gi.tools.run_tool(history_id, tool_id, inputs_down)
for job in result_down.get('jobs', []):
    print(f"  Job ID: {job['id']}")
    down_job_id = job['id']
for out in result_down.get('outputs', []):
    print(f"  Output: {out.get('name')} (HID={out.get('hid')})")

print(f"\nUp Job ID: {up_job_id}")
print(f"Down Job ID: {down_job_id}")

